import{_ as i,o as a,c as e,ak as r}from"./chunks/framework.DvrM7GBU.js";const u=JSON.parse('{"title":"创游 3.x 与 4.x 可观察性差异","description":"","frontmatter":{},"headers":[],"relativePath":"社区分析/专题研究/创游 3.x 与 4.x 可观察性差异.md","filePath":"社区分析/专题研究/创游 3.x 与 4.x 可观察性差异.md","lastUpdated":1776864657000}'),x={name:"社区分析/专题研究/创游 3.x 与 4.x 可观察性差异.md"};function h(t,l,n,d,o,p){return a(),e("div",null,[...l[0]||(l[0]=[r('<h1 id="创游-3-x-与-4-x-可观察性差异" tabindex="-1">创游 3.x 与 4.x 可观察性差异 <a class="header-anchor" href="#创游-3-x-与-4-x-可观察性差异" aria-label="Permalink to “创游 3.x 与 4.x 可观察性差异”">​</a></h1><p>本文基于 <code>资料/其他用户给的解析.txt</code> 中关于 3.x 观察脚本代码的描述，以及现有引擎更新与脚本资料，整理 3.x 与 4.x 在“可观察性”层面的差异线索。</p><blockquote><p>说明：本文主要是研究线索整理，不代表官方确认结论。</p></blockquote><h2 id="_1-为什么研究-可观察性" tabindex="-1">1. 为什么研究“可观察性” <a class="header-anchor" href="#_1-为什么研究-可观察性" aria-label="Permalink to “1. 为什么研究“可观察性””">​</a></h2><p>很多时候，真正限制研究深度的，不是功能本身，而是：</p><ul><li>能不能看到底层表现</li><li>能不能拿到中间结果</li><li>能不能观察脚本生成后的形式</li></ul><p>因此，3.x 和 4.x 的差异，未必只在功能多少，更可能在：</p><ul><li>看得见多少</li><li>调得动多少</li><li>验证路线是否存在</li></ul><hr><h2 id="_2-3-x-的关键线索-可通过-查看数值-观察脚本属性" tabindex="-1">2. 3.x 的关键线索：可通过“查看数值”观察脚本属性 <a class="header-anchor" href="#_2-3-x-的关键线索-可通过-查看数值-观察脚本属性" aria-label="Permalink to “2. 3.x 的关键线索：可通过“查看数值”观察脚本属性”">​</a></h2><p><code>资料/其他用户给的解析.txt</code> 提到：</p><ul><li>在 3.x 中，可以通过“查看数值”查看某个“脚本”属性中的代码</li></ul><p>这条线索非常关键，因为它意味着：</p><ul><li>3.x 某些环境里，脚本并非完全黑箱</li><li>用户可以间接看到积木转换后的文本结构</li><li>可以收集“积木 -&gt; 伪源码片段”的映射</li></ul><p>对于逆向研究来说，这几乎是一个天然观察窗。</p><hr><h2 id="_3-4-x-的问题-能力更强-但黑箱更厚" tabindex="-1">3. 4.x 的问题：能力更强，但黑箱更厚 <a class="header-anchor" href="#_3-4-x-的问题-能力更强-但黑箱更厚" aria-label="Permalink to “3. 4.x 的问题：能力更强，但黑箱更厚”">​</a></h2><p>从现有资料可以看到：</p><ul><li>4.x 明显增加了更多积木、更多数据类型、更多系统能力</li><li>但社区文本同时指出：3.x 不支持 4.x 的部分积木</li></ul><p>这形成一个研究上的矛盾：</p><ul><li>3.x 更容易观察</li><li>4.x 更接近当前真实能力</li></ul><p>所以研究者会遇到：</p><ul><li>3.x 看得到，但不完整</li><li>4.x 更完整，但更难直接看底层</li></ul><hr><h2 id="_4-可观察性差异的三种层面" tabindex="-1">4. 可观察性差异的三种层面 <a class="header-anchor" href="#_4-可观察性差异的三种层面" aria-label="Permalink to “4. 可观察性差异的三种层面”">​</a></h2><h3 id="_4-1-代码可见性" tabindex="-1">4.1 代码可见性 <a class="header-anchor" href="#_4-1-代码可见性" aria-label="Permalink to “4.1 代码可见性”">​</a></h3><p>3.x：</p><ul><li>存在通过“查看数值”侧看脚本代码的可能</li></ul><p>4.x：</p><ul><li>当前资料中没有同等级别的直接可见路径被确认</li></ul><h3 id="_4-2-积木覆盖范围" tabindex="-1">4.2 积木覆盖范围 <a class="header-anchor" href="#_4-2-积木覆盖范围" aria-label="Permalink to “4.2 积木覆盖范围”">​</a></h3><p>3.x：</p><ul><li>可用于研究旧积木或基础积木</li><li>但无法覆盖 4.x 新能力</li></ul><p>4.x：</p><ul><li>支持更丰富的数据类型与脚本块</li><li>但缺乏同样方便的观察窗</li></ul><h3 id="_4-3-调试方式" tabindex="-1">4.3 调试方式 <a class="header-anchor" href="#_4-3-调试方式" aria-label="Permalink to “4.3 调试方式”">​</a></h3><p>4.x：</p><ul><li>从更新记录可知，逐行 Debug、调用栈等能力在增强</li></ul><p>这说明 4.x 虽然可能更黑箱，但也在提供另一种官方调试路径：</p><ul><li>不是直接看生成代码</li><li>而是看执行过程与调用关系</li></ul><hr><h2 id="_5-这意味着研究方法必须分层" tabindex="-1">5. 这意味着研究方法必须分层 <a class="header-anchor" href="#_5-这意味着研究方法必须分层" aria-label="Permalink to “5. 这意味着研究方法必须分层”">​</a></h2><h3 id="用-3-x-做什么" tabindex="-1">用 3.x 做什么 <a class="header-anchor" href="#用-3-x-做什么" aria-label="Permalink to “用 3.x 做什么”">​</a></h3><p>适合：</p><ul><li>看基础积木可能生成什么形式的伪源码</li><li>观察 runtime / gameObject / local / evtParam 等结构</li><li>建立对“积木转执行逻辑”的直觉</li></ul><h3 id="用-4-x-做什么" tabindex="-1">用 4.x 做什么 <a class="header-anchor" href="#用-4-x-做什么" aria-label="Permalink to “用 4.x 做什么”">​</a></h3><p>适合：</p><ul><li>验证当前真实功能行为</li><li>比较新积木的外部表现</li><li>借助官方调试工具观察调用链和执行流程</li></ul><h3 id="最佳策略" tabindex="-1">最佳策略 <a class="header-anchor" href="#最佳策略" aria-label="Permalink to “最佳策略”">​</a></h3><ul><li>用 3.x 建立底层模型猜想</li><li>用 4.x 验证现代版本行为</li><li>不把 3.x 的可见结果机械套到 4.x 全部系统上</li></ul><hr><h2 id="_6-为什么-文本转脚本-在-3-x-4-x-都难" tabindex="-1">6. 为什么“文本转脚本”在 3.x/4.x 都难 <a class="header-anchor" href="#_6-为什么-文本转脚本-在-3-x-4-x-都难" aria-label="Permalink to “6. 为什么“文本转脚本”在 3.x/4.x 都难”">​</a></h2><p>社区文本指出：</p><ul><li>即使看到了伪源码文本</li><li>也不代表能直接从文本反构造成脚本</li></ul><p>原因包括：</p><ul><li>可能有生成器</li><li>可能和积木位置有关</li><li>可能带随机/哈希标识</li><li>文本有转义处理</li></ul><p>这说明“可观察性”与“可逆性”是两回事：</p><ul><li>3.x 更可观察</li><li>但未必可逆</li><li>4.x 更强大</li><li>但也未必更开放</li></ul><hr><h2 id="_7-对知识库建设的启发" tabindex="-1">7. 对知识库建设的启发 <a class="header-anchor" href="#_7-对知识库建设的启发" aria-label="Permalink to “7. 对知识库建设的启发”">​</a></h2><p>这个主题提醒我们，知识库不该只按“功能分类”整理，还应该按“研究手段”整理。</p><p>例如可以建立：</p><ul><li>哪些结论来自官方教程</li><li>哪些来自版本更新</li><li>哪些来自 3.x 侧观测</li><li>哪些来自 4.x 行为验证</li><li>哪些只是社区猜想</li></ul><p>这样后续问答时就能更清楚地区分：</p><ul><li>已确认事实</li><li>高可信推断</li><li>待验证假设</li></ul><hr><h2 id="_8-适合-ai-rag-的关键词" tabindex="-1">8. 适合 AI/RAG 的关键词 <a class="header-anchor" href="#_8-适合-ai-rag-的关键词" aria-label="Permalink to “8. 适合 AI/RAG 的关键词”">​</a></h2><ul><li>3.x</li><li>4.x</li><li>可观察性</li><li>查看数值</li><li>脚本属性</li><li>伪源码</li><li>调用栈</li><li>逐行Debug</li><li>积木兼容</li><li>文本转脚本</li><li>哈希标识</li></ul><hr><h2 id="_9-后续可继续深挖的问题" tabindex="-1">9. 后续可继续深挖的问题 <a class="header-anchor" href="#_9-后续可继续深挖的问题" aria-label="Permalink to “9. 后续可继续深挖的问题”">​</a></h2><ol><li>3.x 中哪些具体积木最适合做伪源码样本收集</li><li>4.x 调试工具是否能间接替代部分源码观察能力</li><li>3.x 与 4.x 的 local / evtParam / runtime 结构是否一致</li><li>不同版本中广播、自定义指令、组件脚本的可观察性差异</li><li>如何建立“3.x 观察结果 -&gt; 4.x 行为验证”的研究链路</li></ol>',71)])])}const c=i(x,[["render",h]]);export{u as __pageData,c as default};
